'use strict';

const POSITIVE_WORDS = new Set([
  'good',
  'great',
  'excellent',
  'positive',
  'fortunate',
  'correct',
  'superior',
  'bullish',
  'rally',
  'surge',
  'gain',
  'up',
  'growth',
  'success',
  'happy',
  'love',
  'awesome',
  'amazing',
  'best',
  'strong'
]);

const NEGATIVE_WORDS = new Set([
  'bad',
  'terrible',
  'poor',
  'negative',
  'unfortunate',
  'wrong',
  'inferior',
  'bearish',
  'drop',
  'crash',
  'loss',
  'down',
  'decline',
  'weak',
  'fail',
  'failure',
  'sad',
  'angry',
  'awful',
  'worst',
  'fear'
]);

function tokenize(text) {
  if (!text) return [];
  return String(text)
    .toLowerCase()
    .match(/[a-z0-9']+/g) || [];
}

function calculateScores(tokens) {
  if (!tokens.length) {
    return {
      neg: 0,
      neu: 1,
      pos: 0,
      compound: 0
    };
  }

  let posCount = 0;
  let negCount = 0;

  for (const token of tokens) {
    if (POSITIVE_WORDS.has(token)) {
      posCount += 1;
    } else if (NEGATIVE_WORDS.has(token)) {
      negCount += 1;
    }
  }

  const total = tokens.length;
  const neuCount = Math.max(0, total - posCount - negCount);

  const pos = posCount / total;
  const neg = negCount / total;
  const neu = neuCount / total;
  const compound = Math.max(-1, Math.min(1, (posCount - negCount) / total));

  return { neg, neu, pos, compound };
}

class SentimentIntensityAnalyzer {
  static polarity_scores(text) {
    const tokens = tokenize(text);
    return calculateScores(tokens);
  }
}

module.exports = { SentimentIntensityAnalyzer };
